    dict(idade="adulto", sexo="masculino", pele="media", cabelo="curto", cor_cabelo="preto", roupa="camisa", cor_roupa="azul", acessorios=["oculos"]),
    dict(idade="jovem", sexo="feminino", pele="morena", cabelo="cacheado", cor_cabelo="castanho", roupa="moletom", cor_roupa="vermelho", acessorios=["fone"]),
